#include "bone-metadata.hpp"
#include <cstdlib>
#include <iostream>
#include <new>
using namespace dome;using namespace dome::detail;using Json=nlohmann::json;
namespace {thread_local long countdown=-1;thread_local bool measuring=false;thread_local size_t allocations=0,hits=0;}
void*operator new(size_t n){if(measuring){++allocations;if(countdown==0){++hits;throw std::bad_alloc();}if(countdown>0)--countdown;}if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void*operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
namespace {
size_t checks=0;void check(bool value,const char*why){if(!value)throw std::runtime_error(why);++checks;}
template<class F>void reject(F f,const char*why){try{f();}catch(const std::exception&){++checks;return;}throw std::runtime_error(why);}
Json record(float length){return {{"version",1},{"length",length},{"space","localY"}};}
Skeleton skeleton(){Skeleton s;Bone a;a.name="Root native bone";Bone b;b.name="Actual second native bone";b.parent=0;b.rest.translation={0,1,0};s.bones={a,b};s.validate();return s;}
ImportedAsset asset(){ImportedAsset a;a.nodes.resize(3);a.nodes[0].extras_json=Json{{"artist",{{"text","exact unrelated"}}},{"domeSculptBone",record(.12f)}}.dump();a.nodes[1].extras_json="null";a.nodes[2].extras_json=Json{{"domeSculptBone",record(.37f)}}.dump();return a;}
template<class Prepare,class Call,class Verify>size_t faults(Prepare prepare,Call call,Verify verify){prepare();allocations=hits=0;countdown=-1;measuring=true;call();measuring=false;const auto count=allocations;for(size_t cut=0;cut<count;++cut){prepare();countdown=long(cut);allocations=hits=0;measuring=true;bool refused=false;try{call();}catch(const std::bad_alloc&){refused=true;}catch(...){measuring=false;countdown=-1;throw;}measuring=false;countdown=-1;check(refused&&hits,"Every measured persistent denial is an actual bad_alloc");verify();}return count;}
}
int main()try{
 Json node={{"name","Source"}};node["extras"]={{"artist",Json{{"unicode","腕"},{"array",{1,2,3}}}}};auto initial=node;check(write_bone_length(node,.37f)&&bone_length_record(node.at("extras"))==.37f,"Exact bounded localY authoring record is written/read");check(node.at("extras").at("artist")==initial.at("extras").at("artist"),"All unrelated source extras stay exact");auto exact=node;check(!write_bone_length(node,.37f)&&node==exact,"Unedited existing record stays verbatim");check(write_bone_length(node,.1f)&&bone_length_record(node.at("extras"))==.1f,"Reset to native default still overrides an existing nondefault record");
 for(Json opaque:std::vector<Json>{nullptr,"opaque source",Json::array({1,2}),false}){Json n={{"extras",opaque}};const auto before=n;check(!write_bone_length(n,.1f)&&n==before,"Unrelated non-object extras stay valid at the implicit native default");reject([&]{write_bone_length(n,.4f);},"Owned length cannot overwrite unrelated non-object extras");check(n==before,"Collision refusal preserves exact source node");}
 std::vector<Json>bad{nullptr,Json::array(),"future",Json{{"version",2},{"length",.2},{"space","localY"}},Json{{"version",1.0},{"length",.2},{"space","localY"}},Json{{"version",1},{"length",0},{"space","localY"}},Json{{"version",1},{"length",1001},{"space","localY"}},Json{{"version",1},{"length",.2},{"space","world"}},Json{{"version",1},{"length",.2},{"space","localY"},{"future",true}}};for(auto invalid:bad){Json n={{"extras",{{"artist",7},{"domeSculptBone",invalid}}}};auto before=n;reject([&]{write_bone_length(n,.3f);},"Unknown reserved type/version/space/fields/range must refuse");check(n==before,"Reserved namespace refusal never overwrites artist data");}
 auto input=asset();auto metadata=source_bone_metadata(input);check(metadata.lengths.size()==3&&metadata.lengths[0]==.12f&&!metadata.lengths[1]&&metadata.lengths[2]==.37f&&metadata.extras[1]&&metadata.extras[1]->is_null(),"Source node identity, absence and explicit null stay distinct");auto s=skeleton();const std::array<uint32_t,2>map{2,0};check(apply_bone_lengths(s,map,metadata)==2&&s.bones[0].length==.37f&&s.bones[1].length==.12f,"Actual source-node to native-slot map applies values instead of node/order/name guessing");reject([&]{apply_bone_lengths(s,std::array<uint32_t,2>{3,0},metadata);},"Out-of-source identity must refuse");check(s.bones[0].length==.37f&&s.bones[1].length==.12f,"Invalid slot map preserves previously accepted rig");reject([&]{source_bone_metadata(input,[]{return true;});},"Source metadata capture honors Cancel");reject([&]{apply_bone_lengths(s,map,metadata,[]{return true;});},"Rig metadata application honors Cancel");
 size_t writer_faults=0,reader_faults=0,rig_faults=0;
 {auto n=initial;writer_faults=faults([&]{n=initial;},[&]{write_bone_length(n,.37f);},[&]{check(n==initial,"Persistent writer failure keeps old node and unrelated extras exact");});}
 reader_faults=faults([]{},[&]{auto parsed=source_bone_metadata(input);},[&]{check(input.nodes[0].extras_json==asset().nodes[0].extras_json,"Persistent source reader failure keeps immutable input exact");});
 {auto current=skeleton();const auto old=current.encode();rig_faults=faults([&]{current=skeleton();},[&]{apply_bone_lengths(current,map,metadata);},[&]{check(current.encode()==old,"Persistent application failure keeps old Skeleton exact");});}
 std::cout<<checks<<" bone metadata checks; persistent boundaries writer="<<writer_faults<<" reader="<<reader_faults<<" rig="<<rig_faults<<'\n';return 0;
}catch(const std::exception&e){measuring=false;countdown=-1;std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
